IF XAxisHomeSignal = 0 THEN
  g_boXAxisHomeSignal := g_biFilter_XAxisZero;
ELSIF XAxisHomeSignal = 1 THEN
  g_boXAxisHomeSignal := g_biFilter_XAxisPosLimit;
ELSE
  g_boXAxisHomeSignal := g_biFilter_XAxisNegLimit;
END_IF;

IF YAxisHomeSignal = 0 THEN
  g_boYAxisHomeSignal := g_biFilter_YAxisZero;
ELSIF YAxisHomeSignal = 1 THEN
  g_boYAxisHomeSignal := g_biFilter_YAxisPosLimit;
ELSE
  g_boYAxisHomeSignal := g_biFilter_YAxisNegLimit;
END_IF;

IF ZAxisHomeSignal = 0 THEN
  g_boZAxisHomeSignal := g_biZAxisHomeSignal;
ELSIF ZAxisHomeSignal = 1 THEN
  g_boZAxisHomeSignal := g_biZAxisPosLimit;
ELSE
  g_boZAxisHomeSignal := g_biZAxisNegLimit;
END_IF;

