IF CNCUAxisHomeSignal = 0 THEN
  g_boCNCUAxisHomeSignal := g_bUAxisHomeZeroSignalNoFilter;
  ELSIF CNCUAxisHomeSignal = 1 THEN
    g_boCNCUAxisHomeSignal := g_bUAxisHomePosSignalNoFilter;
  ELSE
    g_boCNCUAxisHomeSignal := g_bUAxisHomeNegSignalNoFilter;
END_IF;


IF AAxisHomeSignal = 0 THEN
  g_boAAxisHomeSignal := g_boFilter_AAxisZero;
ELSIF AAxisHomeSignal = 1 THEN
  g_boAAxisHomeSignal := g_boFilter_AAxisPosLimit;
ELSE
  g_boAAxisHomeSignal := g_boFilter_AAxisNegLimit;
END_IF;

IF g_nMachineType = 1 OR g_nMachineType = 7 THEN
  IF FeedingAxisHomeSignal = 0 THEN
    g_boFeedingAxisHomeSignal := g_biFeedingHomeSignal;
  ELSIF FeedingAxisHomeSignal = 1 THEN
    g_boFeedingAxisHomeSignal := g_biFeedingPosLimit;
  ELSE
    g_boFeedingAxisHomeSignal := g_biFeedingNegLimit;
  END_IF;
END_IF; 

IF g_nMachineType = 4 OR g_nMachineType = 9 THEN
  (*鼎点和博恩德新增轴的回零处理*)
  IF DDAxisHomeSignal = 0 THEN
    g_boDDAxisHomeSignal := g_biFeedingHomeSignal;
  ELSIF DDAxisHomeSignal = 1 THEN
    g_boDDAxisHomeSignal := g_biDDAxisPosLimit;
  ELSE
    g_boDDAxisHomeSignal := g_biDDAxisNegLimit;
  END_IF;
END_IF;
