IF g_nAntiRejectionFun = 2 THEN
  (*防甩轴*)
  IF g_AntiRejection1HomeSignal = 0 THEN
    g_boAntiRejection1HomeSignal := g_biAntiRejection1HomeSignal;
  ELSIF g_AntiRejection1HomeSignal = 1 THEN
    g_boAntiRejection1HomeSignal := g_biAntiRejection1PosLimit;
  ELSE
    g_boAntiRejection1HomeSignal := g_biAntiRejection1NegLimit;
  END_IF;
END_IF;



g_nZAxisHomeSignal := ZAxisHomeSignal;
g_XAxisHomeSignal := XAxisHomeSignal;
g_YAxisHomeSignal := YAxisHomeSignal;
g_CNCUAxisHomeSignal := CNCUAxisHomeSignal;
g_DDAxisHomeSignal := DDAxisHomeSignal;
